-- SECURITY DEFINER; API roles that may call it: service_role
CREATE OR REPLACE FUNCTION public.notify_community(p_community uuid, p_except uuid, p_type text, p_title text, p_body text, p_link text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.notifications (recipient_id, type, title, body, link)
  select m.profile_id, p_type, p_title, p_body, p_link
  from public.community_members m
  join public.profiles p on p.id = m.profile_id
  where m.community_id = p_community
    and m.status = 'active'
    and p.status = 'active'
    and (p_except is null or p.id <> p_except)
    and not (
      coalesce(p.notif_prefs -> 'muted_markets', '[]'::jsonb)
        @> to_jsonb(p_community::text)
    );
end;
$function$;
